def assert_response(responseBody, globalParam, statusCode, headers):
    if statusCode != 200 or not isinstance(responseBody, dict) or responseBody.get("code") != 0:
        raise Blocked("社区准备请求失败")
    if not responseBody.get("data"):
        raise Blocked("无可用社区，公开 HTTP 没有创建接口")
    if not responseBody["data"][0].get("id"):
        raise Blocked("社区 ID 不可取得")
    assert responseBody.get("requestId")
    return True

def assert_response(responseBody, globalParam, statusCode, headers):
    if statusCode != 200 or not isinstance(responseBody, dict) or responseBody.get("code") != 0:
        raise Blocked("评价分类准备请求失败")
    assert responseBody.get("requestId")
    categories = responseBody.get("data")
    if not isinstance(categories, list) or "reliable" not in categories:
        raise Blocked("缺少 reliable 分类，公开 HTTP 没有创建分类接口")
    return True

def assert_response(responseBody, globalParam, statusCode, headers):
    if statusCode != 200 or not isinstance(responseBody, dict) or responseBody.get("code") != 0:
        raise Blocked("超长评论载体主题创建失败，无法取得超长评论文本")
    assert responseBody.get("requestId")
    data = responseBody["data"]
    if not data.get("id") or not isinstance(data.get("detail"), str) or len(data["detail"]) != 501:
        raise Blocked("载体主题 detail 未完整回显 501 字符，无法构造超长评论")
    return True

def assert_response(responseBody, globalParam, statusCode, headers):
    assert responseBody.get("requestId")
    if statusCode == 200 and responseBody["code"] == 0:
        assert responseBody["data"]["id"] == globalParam["USER_B"]
        return True
    return statusCode == 401 and responseBody["code"] == 40101

